        self.assertEqual(total([10, 20, 30], discount=0), 60)

    def test_total_with_half_discount(self):
        self.assertEqual(total([10, 20, 30], discount=0.5), 30)

    def test_total_with_full_discount(self):
        self.assertEqual(total([10, 20, 30], discount=1), 0)

    def test_total_with_empty_list(self):
        self.assertEqual(total([], discount=0.5), 0)  # empty list returns 0

    def test_total_with_partial_discount(self):
        # additional test case for a different discount
        self.assertEqual(total([5, 15, 10], discount=0.25), 22.5)

    def test_total_invalid_discount_above_one(self):
        with self.assertRaises(ValueError):
            total([10, 20], discount=1.1)

    def test_total_invalid_discount_below_zero(self):
        with self.assertRaises(ValueError):
            total([10, 20], discount=-0.1)


